def coin_change(coins: list, amount: int) -> int:
    # dp[i] 表示凑成金额 i 所需的最少硬币数
    # 初始化为 amount + 1，相当于一个不可能达到的较大值
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0

    # 遍历所有金额，从小到大计算
    for i in range(1, amount + 1):
        # 尝试使用每一种硬币
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    # 如果 dp[amount] 仍为初始值，说明无法凑出
    return dp[amount] if dp[amount] != amount + 1 else -1

from typing import List, Optional


class TreeNode:
    def __init__(self, val: int = 0, left: Optional['TreeNode'] = None, right: Optional['TreeNode'] = None):
        self.val = val
        self.left = left
        self.right = right


def binary_tree_max_path_sum(root: list) -> int:
    """
    计算二叉树中的最大路径和。
    输入 root 为层序遍历数组，元素为整数或 None。
    """
    if not root:
        return 0

    # 根据层序遍历数组构建二叉树
    nodes = []
    for val in root:
        if val is None:
            nodes.append(None)
        else:
            nodes.append(TreeNode(val))

    # 建立父子关系
    for i in range(len(nodes)):
        if nodes[i] is None:
            continue
        left_idx = 2 * i + 1
        right_idx = 2 * i + 2
        if left_idx < len(nodes):
            nodes[i].left = nodes[left_idx]
        if right_idx < len(nodes):
            nodes[i].right = nodes[right_idx]

    tree_root = nodes[0]
    max_sum = float('-inf')

    def dfs(node: Optional[TreeNode]) -> int:
        """
        返回以 node 为起点向下延伸时，能给父节点提供的最大单边路径和。
        同时更新全局最大路径和。
        """
        nonlocal max_sum
        if node is None:
            return 0

        # 左右子树能提供的最大贡献。如果为负数，则不如不选，记为 0。
        left_gain = max(dfs(node.left), 0)
        right_gain = max(dfs(node.right), 0)

        # 当前节点作为路径最高点时的路径和
        current_path_sum = node.val + left_gain + right_gain
        max_sum = max(max_sum, current_path_sum)

        # 返回当前节点能给父节点提供的最大单边贡献
        return node.val + max(left_gain, right_gain)

    dfs(tree_root)
    return int(max_sum)

def minimum_window_substring(s: str, t: str) -> str:
    if not s or not t or len(s) < len(t):
        return ""

    need = {}
    window = {}

    for ch in t:
        need[ch] = need.get(ch, 0) + 1

    left = 0
    right = 0
    valid = 0
    start = 0
    min_len = float("inf")
    required = len(need)

    while right < len(s):
        ch = s[right]
        right += 1

        if ch in need:
            window[ch] = window.get(ch, 0) + 1
            if window[ch] == need[ch]:
                valid += 1

        while valid == required:
            if right - left < min_len:
                start = left
                min_len = right - left

            remove_ch = s[left]
            left += 1

            if remove_ch in need:
                if window[remove_ch] == need[remove_ch]:
                    valid -= 1
                window[remove_ch] -= 1

    return "" if min_len == float("inf") else s[start:start + min_len]

def candy(ratings: list) -> int:
    n = len(ratings)
    if n == 0:
        return 0

    # 每个孩子初始至少 1 颗糖
    candies = [1] * n

    # 从左到右：保证右边评分更高的孩子比左边多
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1

    # 从右到左：保证左边评分更高的孩子比右边多
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)

    # 最少糖果总数
    return sum(candies)


