def split_array_largest_sum(nums: list, k: int) -> int:
    # 二分查找最小的最大子数组和
    left = max(nums)          # 下界：至少能容纳单个最大元素
    right = sum(nums)         # 上界：所有元素放在一个子数组中

    def can_split(limit: int) -> bool:
        # 判断在每段和不超过 limit 的情况下，能否切成不超过 k 段
        pieces = 1
        current_sum = 0

        for num in nums:
            if current_sum + num <= limit:
                current_sum += num
            else:
                # 当前段已满，必须新开一段
                pieces += 1
                current_sum = num

                # 如果需要超过 k 段，说明 limit 太小
                if pieces > k:
                    return False

        return True

    # 二分答案
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1

    return left

def search_in_rotated_sorted_array(nums: list, target: int) -> int:
    """
    在旋转过的升序整数数组中查找 target 的下标。
    如果存在则返回下标，否则返回 -1。
    时间复杂度 O(log n)，空间复杂度 O(1)。
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        # 左半部分有序
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # 右半部分有序
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1


