def split_array_largest_sum(nums: list, k: int) -> int:
    # 检查在最大子数组和不超过 limit 的情况下，能否用不超过 k 段分割完
    def can_split(limit: int) -> bool:
        count = 1
        current_sum = 0
        for num in nums:
            if current_sum + num > limit:
                # 当前段放不下 num，必须新开一段
                count += 1
                current_sum = num
                if count > k:
                    return False
            else:
                current_sum += num
        return True

    # 答案的最小可能值是数组中的最大值
    left = max(nums)
    # 答案的最大可能值是整个数组的和
    right = sum(nums)

    # 二分查找最小的可行 limit
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1

    return left

def valid_parentheses(s: str) -> bool:
    """
    判断字符串 s 中的括号是否有效匹配。
    仅包含 '('、')'、'['、']'、'{'、'}' 时按题意处理；
    若混入其他字符，也会被视为非法并返回 False。
    """
    # 奇数长度不可能完全匹配
    if len(s) % 2 == 1:
        return False

    # 右括号到左括号的映射
    pairs = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    stack = []

    for ch in s:
        if ch in "([{":
            # 左括号入栈
            stack.append(ch)
        else:
            # 非左括号字符：查字典判断是否为合法右括号
            if ch not in pairs:
                return False

            # 右括号必须先判断栈是否为空，再比较栈顶
            if not stack:
                return False

            if stack[-1] != pairs[ch]:
                return False

            # 匹配成功后再弹出
            stack.pop()

    # 遍历结束后栈为空才说明全部匹配
    return not stack

def coin_change(coins: list, amount: int) -> int:
    # dp[i] 表示凑成金额 i 所需的最少硬币个数
    INF = float('inf')
    dp = [INF] * (amount + 1)

    # 凑成金额 0 不需要任何硬币
    dp[0] = 0

    # 外层遍历金额，内层遍历硬币，保证每种硬币可无限次使用
    for i in range(1, amount + 1):
        for coin in coins:
            # 只有当前硬币面额不超过目标金额时才能使用
            if coin <= i:
                # 尝试用一枚当前硬币，更新最少硬币数
                if dp[i - coin] + 1 < dp[i]:
                    dp[i] = dp[i - coin] + 1

    # 如果 dp[amount] 仍为无穷大，说明无法凑出该金额
    return dp[amount] if dp[amount] != INF else -1

def longest_valid_parentheses(s: str) -> int:
    """
    计算最长有效括号子串长度。
    使用双计数器法，两趟扫描，时间复杂度 O(n)，空间复杂度 O(1)。
    """
    left = right = 0
    ans = 0

    # 从左到右扫描：处理右括号不匹配的情况
    for ch in s:
        if ch == '(':
            left += 1
        else:
            right += 1

        if left == right:
            ans = max(ans, 2 * right)
        elif right > left:
            # 右括号多于左括号，当前段不可能再有效，重新计数
            left = right = 0

    left = right = 0

    # 从右到左扫描：处理左括号不匹配的情况
    for ch in reversed(s):
        if ch == '(':
            left += 1
        else:
            right += 1

        if left == right:
            ans = max(ans, 2 * left)
        elif left > right:
            # 左括号多于右括号，当前段不可能再有效，重新计数
            left = right = 0

    return ans


