def valid_parentheses(s: str) -> bool:
    # 括号映射：右括号 -> 对应的左括号
    pairs = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    # 有效的括号串长度一定是偶数，奇数可直接返回 False
    if len(s) % 2 == 1:
        return False

    stack = []

    for ch in s:
        # 遇到左括号，压入栈中
        if ch in '([{':
            stack.append(ch)
        else:
            # 遇到右括号时，栈不能为空，且栈顶必须是同类型左括号
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()

    # 所有括号都匹配完成后，栈必须为空
    return not stack


