def has_cycle(nums: list, pos: int) -> bool:
    # 空链表一定无环
    if not nums:
        return False

    # 定义链表节点
    class ListNode:
        def __init__(self, val):
            self.val = val
            self.next = None

    # 构造链表节点
    nodes = [ListNode(x) for x in nums]

    # 连接相邻节点
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]

    # 如果 pos 合法，则让尾节点指向 pos 对应节点，形成环
    if pos != -1:
        nodes[-1].next = nodes[pos]

    # Floyd 快慢指针判环
    slow = nodes[0]
    fast = nodes[0]

    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next

        if slow is fast:
            return True

    return False

def search_in_rotated_sorted_array(nums: list, target: int) -> int:
    """
    在旋转后的升序数组中查找目标值 target 的下标。
    如果不存在，返回 -1。

    核心思想：
    数组虽然经过旋转，但任意时刻二分后，左右两半中至少有一半是有序的。
    先判断哪一半有序，再判断 target 是否在该有序区间内，从而决定收缩方向。
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if nums[mid] == target:
            return mid

        # 左半部分 [left, mid] 是有序的
        if nums[left] <= nums[mid]:
            # target 在左半部分的有序区间内
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # 右半部分 [mid, right] 是有序的
        else:
            # target 在右半部分的有序区间内
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def binary_tree_max_path_sum(root: list) -> int:
    # 将层序遍历数组转换为二叉树节点
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right

    if not root:
        return 0

    # 根据层序数组构建二叉树
    nodes = []
    for val in root:
        if val is None:
            nodes.append(None)
        else:
            nodes.append(TreeNode(val))

    # 按层序关系连接左右孩子
    child_index = 1
    for i in range(len(nodes)):
        if nodes[i] is None:
            continue
        if child_index < len(nodes):
            nodes[i].left = nodes[child_index]
            child_index += 1
        if child_index < len(nodes):
            nodes[i].right = nodes[child_index]
            child_index += 1

    ans = float("-inf")

    def dfs(node):
        nonlocal ans
        if node is None:
            return 0

        # 左右子树能提供的最大单边路径和，负数则不如不选
        left_gain = max(dfs(node.left), 0)
        right_gain = max(dfs(node.right), 0)

        # 以当前节点为“拐点”的完整路径和
        current_path_sum = node.val + left_gain + right_gain
        ans = max(ans, current_path_sum)

        # 返回给父节点使用的单边最大贡献
        return node.val + max(left_gain, right_gain)

    dfs(nodes[0])
    return ans

def minimum_window_substring(s: str, t: str) -> str:
    if not s or not t or len(s) < len(t):
        return ""

    need = {}
    window = {}

    for ch in t:
        need[ch] = need.get(ch, 0) + 1

    left = 0
    right = 0
    valid = 0
    required = len(need)

    start = 0
    min_len = float("inf")

    while right < len(s):
        ch = s[right]
        right += 1

        if ch in need:
            window[ch] = window.get(ch, 0) + 1
            if window[ch] == need[ch]:
                valid += 1

        while valid == required:
            if right - left < min_len:
                min_len = right - left
                start = left

            left_ch = s[left]
            left += 1

            if left_ch in need:
                if window[left_ch] == need[left_ch]:
                    valid -= 1
                window[left_ch] -= 1

    return "" if min_len == float("inf") else s[start:start + min_len]

def split_array_largest_sum(nums: list, k: int) -> int:
    def can_split(limit: int) -> bool:
        """判断是否能在每段和都不超过 limit 的前提下，切成不超过 k 段。"""
        segments = 1
        current_sum = 0
        for num in nums:
            if num > limit:
                return False
            if current_sum + num > limit:
                segments += 1
                current_sum = num
                if segments > k:
                    return False
            else:
                current_sum += num
        return segments <= k

    left = max(nums)
    right = sum(nums)

    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1

    return left
